// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Initial owner is address(0); only address(0) passes onlyOwner.
        vm.prank(address(0));
        try c.transferOwnership(newOwner) {
            // Rule: after a successful transferOwnership call, owner == newOwner for EVERY admissible input.
            assertTrue(c.owner() == newOwner, "owner must equal newOwner after transferOwnership");
        } catch {
            // The reference never reverts on transferOwnership (once onlyOwner passes), so reaching here
            // means owner stayed address(0) while the caller was authorized.
            assertTrue(c.owner() == address(0) && false, "transferOwnership must not revert");
        }
    }
}
